// Pure detection logic, testable independent of DOM/camera.
// frameOn / frameOff: Uint8ClampedArray-like RGBA pixel buffers, same width/height.
// Returns list of candidate blobs: {x, y, w, h, score}

function toGray(data, w, h) {
  const out = new Float32Array(w * h);
  for (let i = 0, p = 0; i < data.length; i += 4, p++) {
    out[p] = 0.299 * data[i] + 0.587 * data[i + 1] + 0.114 * data[i + 2];
  }
  return out;
}

function detectGlints(frameOnData, frameOffData, w, h, opts = {}) {
  const threshold = opts.threshold ?? 40;      // min brightness delta to count as "lit by flash"
  const minBlobPx = opts.minBlobPx ?? 2;        // ignore noise specks smaller than this
  const maxBlobPx = opts.maxBlobPx ?? 120;      // ignore large lit-up areas (whole wall, not a lens)

  const on = toGray(frameOnData, w, h);
  const off = toGray(frameOffData, w, h);

  // 1. Delta map: positive-only difference (things that got brighter when flash fired)
  const delta = new Float32Array(w * h);
  for (let i = 0; i < delta.length; i++) {
    const d = on[i] - off[i];
    delta[i] = d > threshold ? d : 0;
  }

  // 2. Connected-component labeling (4-connectivity) over thresholded delta
  const labels = new Int32Array(w * h).fill(-1);
  const blobs = [];
  const stack = [];

  for (let idx = 0; idx < delta.length; idx++) {
    if (delta[idx] <= 0 || labels[idx] !== -1) continue;
    const label = blobs.length;
    labels[idx] = label;
    stack.push(idx);
    let minX = idx % w, maxX = idx % w, minY = (idx / w) | 0, maxY = (idx / w) | 0;
    let count = 0, scoreSum = 0;

    while (stack.length) {
      const cur = stack.pop();
      const cx = cur % w, cy = (cur / w) | 0;
      count++;
      scoreSum += delta[cur];
      if (cx < minX) minX = cx;
      if (cx > maxX) maxX = cx;
      if (cy < minY) minY = cy;
      if (cy > maxY) maxY = cy;

      const neighbors = [
        cy > 0 ? cur - w : -1,
        cy < h - 1 ? cur + w : -1,
        cx > 0 ? cur - 1 : -1,
        cx < w - 1 ? cur + 1 : -1,
      ];
      for (const n of neighbors) {
        if (n >= 0 && delta[n] > 0 && labels[n] === -1) {
          labels[n] = label;
          stack.push(n);
        }
      }
    }

    blobs.push({
      x: minX, y: minY,
      w: maxX - minX + 1, h: maxY - minY + 1,
      pixelCount: count,
      score: scoreSum / count,
    });
  }

  // 3. Filter by size: real lens glints are small, tight, bright clusters
  return blobs.filter(b => {
    const area = b.pixelCount;
    const aspect = b.w / b.h;
    return area >= minBlobPx && area <= maxBlobPx && aspect > 0.3 && aspect < 3.0;
  }).sort((a, b) => b.score - a.score);
}

module.exports = { detectGlints, toGray };
