const { detectGlints } = require('./core.js');
const assert = require('assert');

function makeFrame(w, h, baseGray, spots) {
  // spots: [{x,y,size,gray}]
  const data = new Uint8ClampedArray(w * h * 4);
  for (let i = 0; i < w * h; i++) {
    data[i*4] = data[i*4+1] = data[i*4+2] = baseGray;
    data[i*4+3] = 255;
  }
  for (const s of spots) {
    for (let dy = 0; dy < s.size; dy++) {
      for (let dx = 0; dx < s.size; dx++) {
        const x = s.x + dx, y = s.y + dy;
        if (x < 0 || x >= w || y < 0 || y >= h) continue;
        const idx = (y * w + x) * 4;
        data[idx] = data[idx+1] = data[idx+2] = s.gray;
      }
    }
  }
  return data;
}

const W = 100, H = 100;

// Test 1: dark room, torch off = uniform dark; torch on = small bright lens glint appears
{
  const off = makeFrame(W, H, 15, []);
  const on = makeFrame(W, H, 15, [{x: 40, y: 60, size: 3, gray: 220}]);
  const blobs = detectGlints(on, off, W, H, {threshold: 40, minBlobPx: 2, maxBlobPx: 120});
  assert(blobs.length === 1, `expected 1 blob, got ${blobs.length}`);
  assert(blobs[0].x >= 39 && blobs[0].x <= 41, `blob x off: ${blobs[0].x}`);
  console.log('Test 1 (single lens glint detected): PASS');
}

// Test 2: large flash-lit surface (e.g. whole wall got brighter because room is small) should be filtered out as too big
{
  const off = makeFrame(W, H, 15, []);
  const on = makeFrame(W, H, 15, [{x: 0, y: 0, size: 100, gray: 100}]); // whole frame brighter
  const blobs = detectGlints(on, off, W, H, {threshold: 40, minBlobPx: 2, maxBlobPx: 120});
  assert(blobs.length === 0, `expected large area filtered out, got ${blobs.length} blobs`);
  console.log('Test 2 (large lit area correctly rejected): PASS');
}

// Test 3: below-threshold brightness change (ambient flicker) should not register
{
  const off = makeFrame(W, H, 15, []);
  const on = makeFrame(W, H, 15, [{x: 50, y: 50, size: 3, gray: 30}]); // delta only 15, below threshold 40
  const blobs = detectGlints(on, off, W, H, {threshold: 40, minBlobPx: 2, maxBlobPx: 120});
  assert(blobs.length === 0, `expected sub-threshold noise ignored, got ${blobs.length}`);
  console.log('Test 3 (sub-threshold noise ignored): PASS');
}

// Test 4: two separate glints (e.g. two lenses in room) both detected independently
{
  const off = makeFrame(W, H, 15, []);
  const on = makeFrame(W, H, 15, [
    {x: 10, y: 10, size: 3, gray: 200},
    {x: 80, y: 80, size: 3, gray: 200},
  ]);
  const blobs = detectGlints(on, off, W, H, {threshold: 40, minBlobPx: 2, maxBlobPx: 120});
  assert(blobs.length === 2, `expected 2 distinct blobs, got ${blobs.length}`);
  console.log('Test 4 (two distinct glints both found): PASS');
}

// Test 5: score ranks brighter glint higher
{
  const off = makeFrame(W, H, 15, []);
  const on = makeFrame(W, H, 15, [
    {x: 10, y: 10, size: 3, gray: 180},  // dimmer
    {x: 80, y: 80, size: 3, gray: 240},  // brighter
  ]);
  const blobs = detectGlints(on, off, W, H, {threshold: 40, minBlobPx: 2, maxBlobPx: 120});
  assert(blobs.length === 2);
  assert(blobs[0].score > blobs[1].score, 'expected brighter blob ranked first');
  assert(blobs[0].x >= 79 && blobs[0].x <= 81, 'brighter blob should be the 240-gray one');
  console.log('Test 5 (brighter glint ranked first): PASS');
}

console.log('\nALL TESTS PASSED');
