from html.parser import HTMLParser

class IDChecker(HTMLParser):
    def __init__(self):
        super().__init__()
        self.issues = []
        self.seen_ids = {}
    def handle_starttag(self, tag, attrs):
        attr_names = [a[0] for a in attrs]
        dupe_attrs = set(x for x in attr_names if attr_names.count(x) > 1)
        if dupe_attrs:
            self.issues.append(f'Tag <{tag}> has duplicate attribute(s): {dupe_attrs} -- attrs were: {attrs}')
        for name, val in attrs:
            if name == 'id':
                if val in self.seen_ids:
                    self.issues.append(f'Duplicate id=\"{val}\" on <{tag}> (also on <{self.seen_ids[val]}>)')
                self.seen_ids[val] = tag

html = open('index.html').read()
c = IDChecker()
c.feed(html)
if c.issues:
    print('ISSUES FOUND:')
    for i in c.issues: print(' -', i)
else:
    print('No duplicate-id or duplicate-attribute issues found')
